    var url = '';
    if (template && template.resultUrlTemplate) {
        url = template.resultUrlTemplate.split('{ticketKey}').join(ticketKey);
    }
    return (template && template.text ? template.text : '')
        .split('{ticketKey}').join(ticketKey)
        .split('{url}').join(url);
