        mod.commitAndPush('PROJ-123', baseConfig(), {});

        var addCall = commands.filter(function(c) { return c.indexOf('git add . --') === 0; })[0];
        assert.ok(addCall, 'staging command executed — commands: ' + JSON.stringify(commands));
