        var r = guard.extractSubcommand(['-c', 'fetch.recurseSubmodules=no', '--git-dir=/r/.git', 'commit', '-m', 'x']);
        assert.equal(r.subcommand, 'commit');
        assert.deepEqual(r.args, ['-m', 'x']);
    });
});

